// EventToProto converts the stored row (with its belongs-to associations,
// when preloaded) to its proto message. Nil in, nil out.
func EventToProto(m *Event) *eventv1.Event {
	if m == nil {
		return nil
	}
	out := &eventv1.Event{}
	out.Name = m.Name
	out.Uid = fromPtr(m.UID)
	out.Etag = fromPtr(m.Etag)
	out.DeleteTime = goToTs(m.DeleteTime)
	out.ExpireTime = goToTs(m.ExpireTime)
	out.CreateTime = goValToTs(m.CreateTime)
	out.UpdateTime = goValToTs(m.UpdateTime)
	out.DisplayName = fromPtr(m.DisplayName)
	out.Acronym = fromPtr(m.Acronym)
	out.Uri = fromPtr(m.URI)
	out.Type = EventTypePtrToProto(m.Type)
	out.Frequency = FrequencyPtrToProto(m.Frequency)
	out.MandatoryIndicator = m.MandatoryIndicator
	out.SpouseInvitedIndicator = m.SpouseInvitedIndicator
	out.ChildrenInvitedIndicator = m.ChildrenInvitedIndicator
	out.Scope = ScopePtrToProto(m.Scope)
	out.PreEventSetUpIndicator = m.PreEventSetUpIndicator
	out.PreEventSetUpContractor = fromPtr(m.PreEventSetUpContractor)
	out.Status = fromPtr(m.Status)
	out.AttendeeInfo = AttendeeInfoToProto(m.AttendeeInfo)
	for i := range m.Contacts {
		out.Contacts = append(out.Contacts, EventContactToProto(&m.Contacts[i]))
	}
	for i := range m.Infos {
		out.EventInfos = append(out.EventInfos, EventInfoToProto(&m.Infos[i]))
	}
	for i := range m.Sites {
		out.Sites = append(out.Sites, SiteToProto(&m.Sites[i]))
	}
	for i := range m.CustomQuestions {
		out.CustomQuestions = append(out.CustomQuestions, CustomQuestionToProto(&m.CustomQuestions[i]))
	}
	return out
}

// EventFromProto maps the proto message's data fields onto a fresh row.
// It never invents keys or relations: primary keys, resource references, and
// sub-row graph wiring stay with the caller. Nil in, nil out.
func EventFromProto(pb *eventv1.Event) *Event {
	if pb == nil {
		return nil
	}
	m := &Event{}
	// not mapped here: attendee_info (sub-row graph), contacts (sub-row graph), event_infos (sub-row graph), sites (sub-row graph), custom_questions (sub-row graph)
	m.Name = pb.GetName()
	m.UID = toPtr(pb.GetUid())
	m.Etag = toPtr(pb.GetEtag())
	m.DeleteTime = tsToGo(pb.GetDeleteTime())
	m.ExpireTime = tsToGo(pb.GetExpireTime())
	m.DisplayName = toPtr(pb.GetDisplayName())
	m.Acronym = toPtr(pb.GetAcronym())
	m.URI = toPtr(pb.GetUri())
	m.Type = EventTypePtrFromProto(pb.GetType())
	m.Frequency = FrequencyPtrFromProto(pb.GetFrequency())
	m.MandatoryIndicator = pb.MandatoryIndicator
	m.SpouseInvitedIndicator = pb.SpouseInvitedIndicator
	m.ChildrenInvitedIndicator = pb.ChildrenInvitedIndicator
	m.Scope = ScopePtrFromProto(pb.GetScope())
	m.PreEventSetUpIndicator = pb.PreEventSetUpIndicator
	m.PreEventSetUpContractor = toPtr(pb.GetPreEventSetUpContractor())
	m.Status = toPtr(pb.GetStatus())
	return m
}

